import time

def timed(fn):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        fn(*args, **kwargs)
        print(f"took {time.perf_counter() - start:.3f}s")
    return wrapper

@timed
def add(a, b):
    return a + b

print(add(1, 2))

